import java.io.*; import java.util.*; class TestClass { static class Edge implements Comparable<Edge> { int u, v, w; Edge(int u, int v, int w) { this.u = u; this.v = v; this.w = w; } public int compareTo(Edge o) { return Integer.compare(this.w, o.w); } } static class DSU { int[] parent; DSU(int n) { parent = new int[n]; for (int i = 0; i < n; i++) parent[i] = i; } int find(int i) { if (parent[i] == i) return i; return parent[i] = find(parent[i]); } boolean union(int i, int j) { int rootI = find(i); int rootJ = find(j); if (rootI != rootJ) { parent[rootI] = rootJ; return true; } return false; } } static class City { int id, x, y; City(int id, int x, int y) { this.id = id; this.x = x; this.y = y; } } public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine().trim()); while (t-- > 0) { int n = Integer.parseInt(br.readLine().trim()); int[] x = new int[n]; int[] y = new int[n]; StringTokenizer stX = new StringTokenizer(br.readLine()); StringTokenizer stY = new StringTokenizer(br.readLine()); City[] cities = new City[n]; for (int i = 0; i < n; i++) { x[i] = Integer.parseInt(stX.nextToken()); y[i] = Integer.parseInt(stY.nextToken()); cities[i] = new City(i, x[i], y[i]); } List<Edge> edges = new ArrayList<>(); Arrays.sort(cities, new Comparator<City>() { public int compare(City a, City b) { return Integer.compare(a.x, b.x); } }); for (int i = 0; i < n - 1; i++) edges.add(new Edge(cities[i].id, cities[i + 1].id, Math.abs(cities[i].x - cities[i + 1].x))); Arrays.sort(cities, new Comparator<City>() { public int compare(City a, City b) { return Integer.compare(a.y, b.y); } }); for (int i = 0; i < n - 1; i++) edges.add(new Edge(cities[i].id, cities[i + 1].id, Math.abs(cities[i].y - cities[i + 1].y))); Collections.sort(edges); DSU dsu = new DSU(n); long mstWeight = 0; int count = 0; for (Edge e : edges) { if (dsu.union(e.u, e.v)) { mstWeight += e.w; count++; if (count == n - 1) break; } } System.out.println(mstWeight); } } }